fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn gap_at(worldx: i32, h: i32) -> i32 {
    let seg: i32 = worldx / 128;
    let a: i32 = 100 + hash(seg * 13) % (h - 200);
    let b: i32 = 100 + hash((seg + 1) * 13) % (h - 200);
    a + (b - a) * (worldx % 128) / 128
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, (h / 2) * 8);
        host::display::state_set(2, 0);
        host::display::state_set(3, t);
        host::display::state_set(5, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let sec: i32 = (t - host::display::state_get(3)) / 60;
    if host::display::state_get(5) == 1 {
        host::display::clear(0x140a06);
        host::display::draw_string(120, 180, "HIT THE ROCK", 0xff6633, 4);
        host::display::draw_string(120, 250, "FLEW FOR", 0x808080, 2);
        host::display::draw_number(290, 244, host::display::state_get(7), 0xffffff, 3);
        host::display::draw_string(120, 284, "BEST", 0x808080, 2);
        host::display::draw_number(290, 278, host::display::state_get(4), 0x00ff88, 3);
        host::display::draw_string(110, 350, "TAP TO FLY AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut yf: i32 = host::display::state_get(1);
        let mut vy: i32 = host::display::state_get(2);
        if down == 1 { vy = vy - 1; } else { vy = vy + 1; }
        if vy > 6 { vy = 6; }
        if vy < -6 { vy = -6; }
        yf = yf + vy;
        host::display::state_set(1, yf);
        host::display::state_set(2, vy);
        let py: i32 = yf / 8;
        host::display::clear(0x0a0e14);
        let mut sx: i32 = 0;
        while sx < w / 16 {
            let c: i32 = gap_at(t * 4 + sx * 16, h);
            host::display::fill_rect(sx * 16, 0, 16, c - 64, 0x5a3a22);
            host::display::fill_rect(sx * 16, c + 64, 16, h - c - 64, 0x5a3a22);
            sx = sx + 1;
        }
        let c5: i32 = gap_at(t * 4 + 80, h);
        if py < c5 - 56 || py + 16 > c5 + 56 {
            host::display::state_set(5, 1);
            host::display::state_set(7, sec);
            if sec > host::display::state_get(4) {
                host::display::state_set(4, sec);
            }
        }
        host::display::fill_triangle(80, py, 80, py + 16, 100, py + 8, 0x00ddff);
        host::display::fill_rect(74, py + 4, 8, 8, 0x0088aa);
        host::display::draw_number(w - 80, 12, sec, 0xffffff, 3);
        host::display::draw_string(8, 12, "HOLD TO CLIMB", 0x806040, 1);
    }
    host::display::present();
}
